const raw = ($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text) || '';
const prev = $('Parse Backend Output').first().json;

// Try to extract fixed code; fall back to original if extraction fails
let fixedCode = '';
try {
  fixedCode = extract(raw, 'FIXED_CODE').replace('<<<END>>>', '').trim();
} catch(e) {}

// Fall back to original if no fix was produced
if (!fixedCode || fixedCode.length < 50) {
  fixedCode = prev.backend.code;
}

// Patch: remove any remaining @app.before_first_request if LLM missed it
fixedCode = fixedCode.replace(/@app\.before_first_request\s*\n(\s*def \w+\(\):[\s\S]*?)(?=\n@|\ndef |\nclass |\napp\.run|\nif __name__)/g, (match, fnBody) => {
  const bodyLines = fnBody.split('\n').slice(1).map(l => l.replace(/^    /, ''));
  return '\n# (auto-fixed: moved from before_first_request)\n' + bodyLines.join('\n') + '\n';
});

// Patch: strip markdown code fences the LLM may have wrapped code in (```python ... ```)
fixedCode = fixedCode.replace(/^```[\w]*\s*\n?/gm, '').replace(/^```\s*$/gm, '').trim();

// Patch: strip shebang line (#!/usr/bin/env python3) — not needed in Flask, causes SyntaxError if not line 1
fixedCode = fixedCode.replace(/^#!\/.*\n?/m, '');

// Patch: strip leftover shebang fragments like 'sr/bin/env python3' or 'usr/bin/env python3'
fixedCode = fixedCode.replace(/^[a-z]*\/bin\/env\s+\w+[\d.]*\s*\n?/m, '').trim();

// Patch: fix LLM dropping 'from' in Python import statements
// e.g. 'flask import Flask' -> 'from flask import Flask'
fixedCode = fixedCode.replace(/^((?!from |import )\S[\w_]+ import )/gm, 'from $1');

// Patch: if code still has no valid Python imports at all, prepend standard Flask imports
const hasImport = /^(from |import )/m.test(fixedCode);
if (!hasImport) {
  fixedCode = 'from flask import Flask, request, jsonify, abort\nfrom flask_cors import CORS\nimport csv, os, json, uuid\n\n' + fixedCode;
}

return [{ json: { ...prev, backend: { ...prev.backend, code: fixedCode } } }];

